Here's a complete example with both `DataRow` and `DynamicData` approaches:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace PriceCalculator.Tests;

[TestClass]
public class PriceCalculatorTests
{
    private Calculator.PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new Calculator.PriceCalculator();

    // --- DataRow: best for simple inline values ---

    [TestMethod]
    [DataRow(1, 10.00, 10.00)]
    [DataRow(5, 3.50, 17.50)]
    [DataRow(0, 99.99, 0.00)]
    [DataRow(100, 0.01, 1.00)]
    public void CalculateTotal_ReturnsExpected(int quantity, double price, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)price);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 0.10, 90.00, DisplayName = "10% off $100")]
    [DataRow(50.00, 0.25, 37.50, DisplayName = "25% off $50")]
    [DataRow(200.00, 0.00, 200.00, DisplayName = "No discount")]
    [DataRow(80.00, 1.00, 0.00, DisplayName = "100% discount")]
    public void ApplyDiscount_ReturnsExpected(double total, double discount, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)total, (decimal)discount);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData: best for complex types or computed test cases ---

    [TestMethod]
    [DynamicData(nameof(BulkDiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_BulkScenarios(decimal total, decimal discount, decimal expected)
    {
        var result = _calculator.ApplyDiscount(total, discount);
        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> BulkDiscountCases()
    {
        yield return new object[] { 1000m, 0.05m, 950.00m };
        yield return new object[] { 500m, 0.15m, 425.00m };
        yield return new object[] { 249.99m, 0.50m, 125.00m }; // rounds toward midpoint
    }

    // DynamicData with property source
    [TestMethod]
    [DynamicData(nameof(EdgeCases), DynamicDataSourceType.Property)]
    public void CalculateTotal_EdgeCases(int quantity, decimal price, decimal expected)
    {
        var result = _calculator.CalculateTotal(quantity, price);
        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> EdgeCases =>
    [
        [int.MaxValue, 0m, 0m],
        [1, decimal.MaxValue, decimal.MaxValue],
        [1, 0.001m, 0.001m],
    ];

    // --- Negative tests ---

    [TestMethod]
    [DataRow(-1, 10.00)]
    [DataRow(1, -5.00)]
    public void CalculateTotal_InvalidInput_Throws(int quantity, double price)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(quantity, (decimal)price));
    }

    [TestMethod]
    [DataRow(100.00, -0.10)]
    [DataRow(100.00, 1.50)]
    public void ApplyDiscount_InvalidDiscount_Throws(double total, double discount)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)total, (decimal)discount));
    }
}
```

**Key best practices shown:**

| Practice | Why |
|----------|-----|
| `DataRow` for simple primitives | Inline, readable, no extra methods |
| `DynamicData` with `Method`/`Property` | Supports `decimal`, complex objects, computed data |
| `DisplayName` on DataRow | Clear test explorer output |
| `[TestInitialize]` for setup | Avoid repeated construction |
| Edge cases + negative tests | Full coverage of boundaries |
| `yield return` in method source | Lazy, easy to extend |

**Note:** `DataRow` only supports compile-time constants (`double`, `int`, `string`, etc.), so use `DynamicData` when you need `decimal` literals or object inputs directly.
